// Package propose turns an attributed cause into candidate lessons.
//
// Proposals are rule-derived on purpose: a proposal is only a hypothesis, and a
// hypothesis generated by the same model that failed is not independent
// evidence. The evaluate stage decides whether it survives.
package propose

import (
	"fmt"
	"strings"

	"ragflow/internal/harness/rsi/attribute"
	"ragflow/internal/harness/rsi/signal"
)

// Proposal is one candidate lesson.
type Proposal struct {
	Kind  string
	Title string
	Body  string
	Cause attribute.Cause
}

// FromCause returns the candidate lessons for one cause. Slice order is stable
// so evaluation results stay comparable across cycles.
func FromCause(cause attribute.Cause, s signal.Signal) []Proposal {
	switch cause {
	case attribute.CauseRetrievalShortage:
		return []Proposal{{
			Kind:  "retrieval",
			Title: "Establish evidence before concluding",
			Body: "When a question names an entity or a relationship, locate the passages that mention it first. " +
				"Use search_chunks for meaning, search_bm25_chunks for distinctive terms, and grep_chunks for literal IDs. " +
				"If the first leg returns nothing useful, change the leg or the wording before answering.",
			Cause: cause,
		}}
	case attribute.CauseToolMisuse:
		return []Proposal{{
			Kind:  "tool_use",
			Title: "Read the tool contract before calling it",
			Body: "Pass only identifiers that came from a previous tool result, and stay inside the bound dataset scope. " +
				"A tool_error means the call was wrong, not that the corpus lacks the answer: fix the arguments and retry the same tool once.",
			Cause: cause,
		}}
	case attribute.CauseCitationMissing:
		return []Proposal{{
			Kind:  "citation",
			Title: "Every claim carries a chunk reference",
			Body: "Ground each sentence of the final answer in a passage that was actually retrieved. " +
				"If a claim has no supporting chunk, either retrieve it or drop the claim.",
			Cause: cause,
		}}
	case attribute.CauseBudgetExhausted:
		return []Proposal{{
			Kind:  "planning",
			Title: "Converge instead of re-searching the same gap",
			Body: "If two rounds return the same evidence, stop searching: report what is established, name what is missing, " +
				"and answer the part the evidence supports.",
			Cause: cause,
		}}
	case attribute.CauseEmptyAnswer:
		return []Proposal{{
			Kind:  "answering",
			Title: "Always return what is established",
			Body: "A run must end with text. If the evidence is partial, state the partial answer and name the unresolved part. " +
				"Never end a turn with an empty message.",
			Cause: cause,
		}}
	default:
		return nil
	}
}

// Fingerprint identifies a proposal independent of the run that produced it, so
// repeated evidence for the same lesson can be counted instead of duplicated.
func (p Proposal) Fingerprint() string {
	return strings.Join([]string{p.Kind, p.Title}, "|")
}

// Describe renders the proposal for logs.
func (p Proposal) Describe() string {
	return fmt.Sprintf("%s: %s (%s)", p.Kind, p.Title, p.Cause)
}
